pub const HEADER: &str = "// GENERATED by `cargo run -p sim-api --features ts --example contract_ts` (npm run gen:contract). Do not edit.\n// Source of truth: the wire types in crates/sim-api. Hand-written aliases live in index.ts.\n\n";

