/// The generated file: every declaration exported, sorted by type name.
pub fn generate() -> String {
    let mut v: Vec<String> = decls()
        .into_iter()
        .map(|(_, d)| format!("export {d}"))
        .collect();
    v.sort();
    let mut out = String::from(HEADER);
    out.push_str(&format!(
        "export const SCHEMA_VERSION = {};\n\nexport const CONTRACT_VERSION = \"{}\";\n\n",
        crate::SCHEMA_VERSION,
        crate::CONTRACT_VERSION
    ));
    for d in v {
        out.push_str(&d);
        out.push_str("\n\n");
    }
    out
}
